#!/usr/bin/env python3
"""Minimal VT100 screen emulator: reconstruct final screen (text + attrs) from captured PTY bytes."""
import sys, re

def emulate(data, rows=24, cols=80):
    grid = [[[" ", ""] for _ in range(cols)] for _ in range(rows)]
    r = c = 0
    attr = ""
    i = 0
    n = len(data)
    while i < n:
        ch = data[i]
        if ch == 0x1b:
            if i + 1 < n and data[i+1:i+2] == b"[":
                m = re.match(rb"\x1b\[([0-9;?]*)([@-~])", data[i:i+20])
                if m:
                    params = m.group(1).decode()
                    final = chr(m.group(2)[0])
                    i += m.end()
                    parts = params.lstrip("?").split(";") if params else []
                    nums = [int(p) if p else 0 for p in parts]
                    if final == "H" or final == "f":
                        r = (nums[0]-1) if len(nums) > 0 and nums[0] else 0
                        c = (nums[1]-1) if len(nums) > 1 and nums[1] else 0
                    elif final == "A": r = max(0, r - (nums[0] or 1 if nums else 1))
                    elif final == "B": r = min(rows-1, r + (nums[0] or 1 if nums else 1))
                    elif final == "C": c = min(cols-1, c + (nums[0] or 1 if nums else 1))
                    elif final == "D": c = max(0, c - (nums[0] or 1 if nums else 1))
                    elif final == "G": c = max(0, (nums[0]-1) if nums and nums[0] else 0)
                    elif final == "d": r = max(0, (nums[0]-1) if nums and nums[0] else 0)
                    elif final == "K":
                        mode = nums[0] if nums else 0
                        if mode == 0:
                            for x in range(c, cols): grid[r][x] = [" ", ""]
                        elif mode == 1:
                            for x in range(0, c+1): grid[r][x] = [" ", ""]
                        else:
                            for x in range(cols): grid[r][x] = [" ", ""]
                    elif final == "J":
                        mode = nums[0] if nums else 0
                        if mode in (2, 3):
                            grid = [[[" ", ""] for _ in range(cols)] for _ in range(rows)]
                    elif final == "m":
                        attr = params
                    continue
                else:
                    i += 2
                    continue
            elif data[i+1:i+2] == b"]":
                # OSC: skip to terminator
                end1 = data.find(b"\x1b\\", i)
                end2 = data.find(b"\x07", i)
                ends = [e for e in (end1, end2) if e >= 0]
                if ends:
                    e = min(ends)
                    i = e + (2 if e == end1 else 1)
                else:
                    i = n
                continue
            else:
                i += 2
                continue
        elif ch == 0x0d:
            c = 0; i += 1
        elif ch == 0x0a:
            r = min(rows-1, r+1); i += 1
        elif ch == 0x08:
            c = max(0, c-1); i += 1
        elif ch < 0x20:
            i += 1
        else:
            # decode utf-8 char
            try:
                chs = data[i:i+4].decode("utf-8", "strict")[0]
                blen = len(chs.encode("utf-8"))
            except Exception:
                chs = "�"; blen = 1
            if r < rows and c < cols:
                grid[r][c] = [chs, attr]
            c += 1
            i += blen
    return grid

def render(grid):
    lines = []
    for row in grid:
        txt = ""
        for cell in row:
            if cell[1]:
                txt += f"\x1b[{cell[1]}m{cell[0]}\x1b[0m"
            else:
                txt += cell[0]
        lines.append(txt.rstrip())
    return "\n".join(lines)

def render_plain(grid):
    return "\n".join("".join(cell[0] for cell in row).rstrip() for row in grid)

if __name__ == "__main__":
    data = open(sys.argv[1], "rb").read()
    rows = int(sys.argv[2]) if len(sys.argv) > 2 else 24
    cols = int(sys.argv[3]) if len(sys.argv) > 3 else 80
    g = emulate(data, rows, cols)
    if "--plain" in sys.argv:
        print(render_plain(g))
    else:
        print(render(g))

