#!/usr/bin/env python3
import sys, json, subprocess
sys.path.insert(0, '/tmp')
from screen import emulate, render_plain

def run(cwd, keys, args=None, rows=24, cols=80):
    spec = {"exe": "/workspace/executable", "args": args or [], "cwd": cwd,
            "rows": rows, "cols": cols, "keys": keys}
    p = subprocess.run(["python3", "/tmp/drive.py", json.dumps(spec)],
                       capture_output=True)
    return p.stdout

def cursor_of(g):
    """Return highlighted (bg 99) text run and its position."""
    for ri, row in enumerate(g):
        run_txt = ""
        start = None
        for ci, c in enumerate(row):
            if "48;5;99" in c[1]:
                if start is None: start = ci
                run_txt += c[0]
            elif start is not None:
                break
        if start is not None:
            return ri, start, run_txt
    return None

def probe(cwd, keys, args=None, rows=24, cols=80, label=""):
    out = run(cwd, keys, args, rows, cols)
    g = emulate(out, rows, cols)
    hdr = ''.join(c[0] for c in g[0]).rstrip()
    cur = cursor_of(g)
    print(f"{label} header={hdr!r} cursor={cur}")
    return out, g

if __name__ == "__main__":
    pass
